head.script:
scwin.onpageload = function() {

};

scwin.grid1_onafteredit = function(row,col,value) {
	var log = localStorage.getItem('log1')
	localStorage.setItem('log1', 'grid1_onafteredit, '+log)
    console.log("grid1_onafteredit!!!!!!!!!!!!");
};

scwin.grid1_onviewchange = function(info) {
	localStorage.setItem('log1', 'grid1_onviewchange')
    console.log("grid1_onviewchange!!!!!!!!!!!!");
};

		scwin.fireDbClick = function(node) {
			if (document.createEventObject) {
				node.fireEvent('ondblclick');
			} else if (document.createEvent) {
				var evt = document.createEvent('MouseEvents');
				evt.initEvent('dblclick', true, false);
				node.dispatchEvent(evt);
			} else if (typeof node.ondblclick == 'function') {
				node.ondblclick();
			}
		}
		scwin.Dbclick = function(id) {
			var el = WebSquare.wUnit.getDomById(id);
			scwin.fireDbClick(el);
		}

		scwin.simulateWrapper = function(target, type, options) {
			WebSquare.wUnit.getJq(target).simulate(type, options);
		}
		scwin.setSimulate1 = function() {
			scwin.simulateWrapper('#G_'+$p.di+'grid1__col1', 'key-sequence', {
				sequence: '22'
			});			
		}
		scwin.setSimulate2 = function() {
			scwin.simulateWrapper('#grid1_cell_0_0', 'key-combo', {
				combo: 'ENTER'
			});
		}

		scwin.checkVal1 = function() {
			return localStorage.getItem('log1') == 'grid1_onafteredit, grid1_onviewchange';
		}		
		scwin.unitTest = function() {
			//Unit
			WebSquare.wUnit.start();
			WebSquare.wUnit.addCommand("pause", "500");
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_cell_0_0').click()");
			WebSquare.wUnit.addCommand("pause", "400");
			WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grid1_cell_0_0')");
			WebSquare.wUnit.addCommand("pause", "500");			
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_'+$p.id+'grid1__col1').value = '22'");
			WebSquare.wUnit.addCommand("pause", "500");
			WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
			WebSquare.wUnit.addCommand("pause", "500");

			WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
			WebSquare.wUnit.addCommand("pause", "500");

			//Run test and stop
			WebSquare.wUnit.run();
			WebSquare.wUnit.stop();
		}	
		scwin.unitTest()
		localStorage.removeItem("log1");
